# React Shopping Cart with Redux Toolkit

Here's a complete shopping cart component with Redux Toolkit state management:

## 1. Store Configuration

```javascript
// store/store.js
import { configureStore } from '@reduxjs/toolkit';
import cartReducer from '../features/cartSlice';

export const store = configureStore({
  reducer: {
    cart: cartReducer,
  },
});

export default store;
```

## 2. Cart Slice

```javascript
// features/cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  totalItems: 0,
  totalPrice: 0,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addToCart: (state, action) => {
      const { id, name, price, image, quantity = 1 } = action.payload;

      // Check if item already exists in cart
      const existingItem = state.items.find(item => item.id === id);

      if (existingItem) {
        // Update existing item quantity
        existingItem.quantity += quantity;
      } else {
        // Add new item
        state.items.push({
          id,
          name,
          price,
          image,
          quantity,
        });
      }

      // Update totals
      state.totalItems += quantity;
      state.totalPrice += price * quantity;
    },

    removeFromCart: (state, action) => {
      const itemId = action.payload;
      const itemToRemove = state.items.find(item => item.id === itemId);

      if (itemToRemove) {
        state.totalItems -= itemToRemove.quantity;
        state.totalPrice -= itemToRemove.price * itemToRemove.quantity;

        // Remove from array
        state.items = state.items.filter(item => item.id !== itemId);
      }
    },

    updateQuantity: (state, action) => {
      const { id, quantity } = action.payload;
      const item = state.items.find(item => item.id === id);

      if (item && quantity >= 0) {
        const oldQuantity = item.quantity;
        const quantityDiff = quantity - oldQuantity;

        item.quantity = quantity;
        state.totalItems += quantityDiff;
        state.totalPrice += item.price * quantityDiff;
      }
    },

    clearCart: (state) => {
      state.items = [];
      state.totalItems = 0;
      state.totalPrice = 0;
    },
  },
});

